    try:
        with urllib.request.urlopen(urllib.request.Request(RELAY + path, body, headers, method="POST"), timeout=5) as resp:
            return json.loads(resp.read())["delivery_id"]
    except urllib.error.HTTPError as exc:
        if exc.code == 410:
            return None
        raise

